<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
import ProductPackageManager from './ProductPackageManager.vue'
import CommerceIntegrationManager from './CommerceIntegrationManager.vue'
const $q=useQuasar(),busy=ref(false),loading=ref(false),productType=ref('desktop')
const definitions={desktop:{title:'Desktop · executável',route:'/whatsapp-solucoes',price:397,original:497,description:'Aplicativo pronto para Windows. Planos de 1, 6 ou 12 meses, sem código-fonte.'},cloud:{title:'Whitelabel · código-fonte / Cloud',route:'/whatsapp-solucoes-whitelabel',price:1997,original:2490,description:'Produto separado com código-fonte editável, pacote Cloud e token vitalício. Não inclui o executável Desktop.'}}
const current=computed(()=>definitions[productType.value])
const form=reactive({available:true,price:397,original:497,permanent:false,durationDays:365,desktopPlans:[],media:{},kitTerms:{title:'',version:'',content:''}})
const mediaFields=[{key:'teamAccess',label:'Múltiplos atendentes'},{key:'heroVideo',label:'Vídeo principal (MP4 ou YouTube)'},{key:'heroPoster',label:'Capa do vídeo'},{key:'cloudDashboard',label:'Painel de notificações'},{key:'scheduler',label:'Programação de envios'},{key:'mobilePush',label:'App e notificações'},{key:'whiteLabel',label:'Personalização de marca'},{key:'botFlow',label:'Editor de fluxos'},{key:'botChats',label:'Conversas e atendimento'}]
const headers=()=>({headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}})
function apply(value){const d=current.value;Object.assign(form,{available:value.available!==false,price:(value.priceCents??d.price*100)/100,original:(value.originalPriceCents??d.original*100)/100,permanent:value.permanent??productType.value==='cloud',durationDays:value.durationDays??365,desktopPlans:(value.desktopPlans||[]).map(p=>({...p,price:p.priceCents/100})),media:{...value.media},kitTerms:{title:'',version:'',content:'',...value.kitTerms}})}
async function load(type=productType.value){if(busy.value)return;productType.value=type;loading.value=true;try{apply((await api.get('/admin/products/aitonotify/offer',{...headers(),params:{productType:type}})).data.data)}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Não foi possível carregar este produto.'})}finally{loading.value=false}}
async function save(){busy.value=true;try{const cents=v=>Math.round(Number(String(v).replace(',','.'))*100);const body={productType:productType.value,available:form.available,priceCents:cents(form.price),originalPriceCents:cents(form.original),permanent:form.permanent,durationDays:Number(form.durationDays),desktopPlans:productType.value==='desktop'?form.desktopPlans.map(p=>({months:p.months,enabled:p.enabled,priceCents:cents(p.price)})):undefined,media:form.media,kitTerms:form.kitTerms};apply((await api.put('/admin/products/aitonotify/offer',body,headers())).data.data);$q.notify({type:'positive',message:'Preço, prazo, apresentação e termos deste produto atualizados.'})}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Confira os dados do produto.'})}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><q-card flat bordered class="offer-admin q-mb-xl"><q-card-section><span class="offer-eyebrow">CATÁLOGO AITOSOFTWARES</span><h2>Dois produtos. Licenças independentes.</h2><p>Preços, validade, termos e arquivos são configurados por produto. O carrinho permite comprar os dois; cada item recebe seu próprio token.</p></q-card-section><q-tabs :model-value="productType" @update:model-value="load" align="left" active-color="teal-3" inline-label><q-tab name="desktop" icon="mdi-microsoft-windows" label="Executável Desktop" :disable="busy||loading"/><q-tab name="cloud" icon="mdi-source-repository" label="Código-fonte Whitelabel" :disable="busy||loading"/></q-tabs><q-inner-loading :showing="loading" color="teal-3"/><q-form @submit="save"><q-card-section><h3>{{current.title}}</h3><p>{{current.description}}</p><a :href="current.route" target="_blank" rel="noopener">Abrir página de venda ↗</a></q-card-section><q-card-section class="offer-fields"><q-toggle color="teal-4" v-model="form.available" label="Disponível para compra"/><q-toggle v-if="productType!=='desktop'" color="teal-4" v-model="form.permanent" label="Token vitalício (sem vencimento programado)"/><q-input v-if="productType!=='desktop'" dark stack-label v-model="form.price" outlined label="Preço de venda (R$)" inputmode="decimal"/><q-input v-if="productType!=='desktop'" dark stack-label v-model="form.original" outlined label="Preço de referência (R$)" inputmode="decimal"/><q-input v-if="productType!=='desktop'&&!form.permanent" dark stack-label v-model.number="form.durationDays" outlined type="number" min="1" max="36500" label="Validade inicial do token em dias" hint="Desktop: 365 dias por padrão. O prazo é registrado no pedido e na emissão."/><div v-if="productType==='desktop'" class="offer-fields"><div v-for="plan in form.desktopPlans" :key="plan.months"><q-toggle v-model="plan.enabled" :label="plan.label+' · '+plan.months+' mês(es)'"/><q-input dark outlined v-model="plan.price" label="Preço total do período (R$)" inputmode="decimal"/></div></div><q-banner rounded class="offer-note">Alterações valem para novas compras. Licenças já emitidas têm a validade administrada individualmente, sem mudança automática das condições anteriores.</q-banner></q-card-section><q-expansion-item dark icon="mdi-image-multiple-outline" label="Vídeo, imagens e prints desta página" class="q-mx-md"><q-card-section class="offer-fields"><q-input dark stack-label v-for="field in mediaFields" :key="field.key" v-model.trim="form.media[field.key]" outlined :label="field.label" hint="URL HTTPS. Vazio mantém o demonstrativo padrão."/></q-card-section></q-expansion-item><q-expansion-item dark icon="mdi-file-document-check-outline" label="Termos de uso deste produto" class="q-mx-md"><q-card-section><p>Texto simples com quebras de linha. O checkout registra a versão aplicada à compra. Ao alterar título ou conteúdo, aumente a versão antes de salvar.</p><div class="offer-fields"><q-input dark stack-label v-model="form.kitTerms.title" outlined label="Título dos termos" maxlength="160"/><q-input dark stack-label v-model="form.kitTerms.version" outlined label="Versão" maxlength="40"/></div><q-input dark stack-label class="q-mt-md" v-model="form.kitTerms.content" outlined type="textarea" :rows="14" label="Texto dos termos" maxlength="30000" counter/></q-card-section></q-expansion-item><q-card-actions align="right"><q-btn unelevated color="teal-7" no-caps type="submit" label="Salvar este produto" :loading="busy" :disable="loading"/></q-card-actions></q-form><CommerceIntegrationManager/><ProductPackageManager/></q-card></template>
<style scoped>.offer-admin{position:relative;background:#092324;color:#effffb;border-color:#2b5855;border-radius:18px;overflow:hidden}.offer-admin h2{font-size:25px;line-height:1.3;margin:8px 0}.offer-admin h3{font-size:21px;margin:8px 0}.offer-admin p{color:#c0dcd2;font-size:13px;line-height:1.8}.offer-admin a{color:#a1ffe0;font-size:12px}.offer-eyebrow{font-size:10px;letter-spacing:.14em;color:#8fffee}.offer-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.offer-note{background:#173f34;color:#ccebdd;font-size:12px;line-height:1.8}.offer-admin :deep(.q-field__native),.offer-admin :deep(.q-field__label),.offer-admin :deep(.q-field__messages){color:#e1f6ec}.offer-admin :deep(.q-field__control:before){border-color:#52766e}@media(max-width:700px){.offer-fields{grid-template-columns:1fr}}</style>
